function beginFarewell(){if(active!=='house'||farewellPending)return;gathering=false;storyShown=false;farewellDone=false;if(seatState)toggleSeat();seatApproach=false;const host=guests[0];if(host.seated||host.from){host.actor.position.set(-4.4,.25,7);host.seated=false;host.from=null;posePerson(host.actor,0,1);}const target={x:HX+host.actor.position.x,z:HZ+host.actor.position.z+1.5};farewellPending=requestWalk(target);autoTravel=false;toast('走到主人面前，道一声珍重。');}
function updateGathering(dt){if(active!=='house')return;for(const g of guests){if(gathering&&!g.from){if(g.path?.length){const next=g.path[0],delta=new THREE.Vector3(next.x-HX-g.actor.position.x,0,next.z-HZ-g.actor.position.z),d=delta.length();if(d<.08)g.path.shift();else{const step=Math.min(d,dt*2);g.actor.position.addScaledVector(delta,step/d);g.actor.rotation.y=Math.atan2(delta.x,delta.z);posePerson(g.actor,step,dt);}}else{g.from=g.actor.position.clone();g.sit=0;}}if(g.from)poseGuest(g,dt);}
 if(gathering&&!storyShown&&seatState?.time===1&&guests.every(g=>g.seated)){storyShown=true;toast('村人：先祖避秦时战乱，携家人来到此处，从此未曾出去。');modal('<div class="eyebrow">围炉闲话</div><h2>此间不知岁月</h2><p>村人：先祖为了躲避秦时战乱，带着家人乡邻来到这里，从此不再出去。</p><p>渔人：如今已是晋朝，中间还经历了汉、魏。</p><p>大家围桌听罢，感叹惋惜，又为你添上酒饭。</p><button class="primary" id="finish-talk">记下相遇，继续闲坐</button>');$('#finish-talk').onclick=()=>{collect();$('#modal').close()};}
 if(farewellPending&&!walkPath.length){const host=guests[0].actor,dx=HX+host.position.x-player.position.x,dz=HZ+host.position.z-player.position.z;if(Math.hypot(dx,dz)<2.1){farewellPending=false;player.rotation.y=Math.atan2(dx,dz);host.rotation.y=Math.atan2(-dx,-dz);modal('<div class="eyebrow">临行道别</div><h2>主人，叨扰多日了</h2><p>渔人：多谢款待，我该回去了。</p><p>主人：一路珍重。此间之事，不足为外人道也。</p><button class="primary" id="farewell-leave">道别，走出院门</button><button class="secondary" id="farewell-stay">再留一会儿</button>');$('#farewell-leave').onclick=()=>{farewellDone=true;$('#modal').close();beginHomeward()};$('#farewell-stay').onclick=()=>$('#modal').close();}}
}

function changeConnectedScene(to,reason){const from=active,position=player.position.clone(),eye=camera.position.clone(),look=controls.target.clone(),phase=player.userData.rig.phase;collect();routeHistory.push({from,to,reason});enterScene(to);if(to==='grove'&&parkedAtBank){groveWalking=true;heroBoat.visible=false;playerRing.visible=true;}syncParkedBoat();setLabels();player.position.copy(position);player.position.y=nav[to].floor(position.x,position.z);player.userData.rig.phase=phase;tween=null;camera.position.copy(eye);controls.target.copy(look);controls.minDistance=3;controls.enabled=true;transitioning=false;}

function startTransition(to,reason){if(transitioning)return;collect();transitioning=true;autoTravel=false;walkPath=[];keys.clear();controls.enabled=false;sceneTransition={to,reason,time:0,committed:false};routeHistory.push({from:active,to,reason});const el=$('#transition');el.style.transition='none';el.style.opacity='0';el.classList.add('show');el.querySelector('span').textContent=reason;el.querySelector('strong').textContent=to==='overview'?'复行数十步，豁然开朗。':data[to].verse;}
function updateTransition(dt){if(!sceneTransition)return;controls.enabled=false;const tr=sceneTransition;tr.time+=dt;const duration=reduced?.16:1.15,u=Math.min(tr.time/duration,1);$('#transition').style.opacity=String(Math.sin(u*Math.PI));if(u>=.5&&!tr.committed){tr.committed=true;enterScene(tr.to,{preserveTransition:true});resetView(false)}if(u===1){sceneTransition=null;transitioning=false;$('#transition').classList.remove('show');$('#transition').style.opacity='';controls.enabled=true}}
function beginHomeward(){boardingApproach=false;homeward=[{scene:'house',x:HX,z:HZ+16.5},{scene:'pond',x:9,z:-70.1},{scene:'cave',x:7.5,z:-42}];if(parkedAtBank)homeward.push({scene:'grove',...landing});returnedToCreek=false;autoTravel=requestWalk(homeward[0]);toast('沿村路穿过山口，回到系舟的溪边。');}
function updateHomeward(){if(!homeward.length||walkPath.length||!autoTravel)return;const goal=homeward[0];if(Math.hypot(player.position.x-goal.x,player.position.z-goal.z)>.2){autoTravel=requestWalk(goal);return;}homeward.shift();if(!homeward.length){returnedToCreek=true;autoTravel=false;setLabels();toast('回到溪边了，小舟仍系在原处。');return;}const next=homeward[0];if(active!==next.scene)changeConnectedScene(next.scene,'沿原路回到溪边');autoTravel=requestWalk(next);}
function returnBerth(){return parkedAtBank?{shore:{...landing},boat:groveShoreBoat.position.clone(),yaw:groveShoreBoat.rotation.y,t:landingT}:{shore:{x:7.5,z:-42},boat:new THREE.Vector3(3.5,.15,-42.8),yaw:mooredBoat.rotation.y,t:null};}
function atCreekBerth(){const {shore}=returnBerth();return !heroBoat.visible&&!boarding&&!bankTransfer&&!seekingAgain&&Math.hypot(player.position.x-shore.x,player.position.z-shore.z)<8;}
function syncParkedBoat(){const onLand=!heroBoat.visible&&!seekingAgain;mooredBoat.visible=onLand&&!parkedAtBank;groveShoreBoat.visible=onLand&&parkedAtBank;}
function updateCreekReturn(){if(boarding||heroBoat.visible||bankTransfer||seekingAgain)return;
 if(!homeward.length){let to=null;if(['overview','pond','house'].includes(active)&&player.position.z> -69.4&&nav.cave.valid(player.position.x,player.position.z))to='cave';else if(active==='cave'&&parkedAtBank&&player.position.z> -41.6)to='grove';if(to){const remaining=walkPath.map(p=>({...p})),walking=autoTravel,heldKeys=[...keys];changeConnectedScene(to,'沿原路走回系舟处');walkPath=remaining;autoTravel=walking;heldKeys.forEach(key=>keys.add(key));}}
 const ready=atCreekBerth();if(ready!==returnedToCreek){returnedToCreek=ready;setLabels();if(ready)toast('点击小舟或“登船 · 划回桃林”，即可离开。');}
 const {shore}=returnBerth();if(boardingApproach&&!homeward.length&&Math.hypot(player.position.x-shore.x,player.position.z-shore.z)<.2)startDepartureBoarding();
}
function boardForDeparture(){if(boarding||bankTransfer||heroBoat.visible||seekingAgain||docking)return;homeward=[];walkPath=[];keys.clear();landingPending=false;walkingToCave=false;boardingApproach=true;const berth=returnBerth();
 if(Math.hypot(player.position.x-berth.shore.x,player.position.z-berth.shore.z)<.2){startDepartureBoarding();return;}
 if(parkedAtBank&&active!=='grove'){homeward=[{scene:'cave',x:7.5,z:-42},{scene:'grove',...berth.shore}];autoTravel=requestWalk(homeward[0]);}else autoTravel=requestWalk(berth.shore);
 if(!autoTravel){boardingApproach=false;homeward=[];toast('沿岸边木板路靠近小舟后，再点登船。');}else toast('走到木板路的登船处，再登舟离开。');
}
function startDepartureBoarding(){const berth=returnBerth();boardingApproach=false;homeward=[];autoTravel=false;walkPath=[];keys.clear();boarding={time:0,from:player.position.clone(),boat:berth.boat,yaw:berth.yaw,t:berth.t};toast('登上小舟，沿桃林驶回溪流下游。');}
function updateBoarding(dt){const b=boarding;b.time+=dt;if(b.undock){const u=Math.min(b.time/1.5,1),before=heroBoat.position.clone();heroBoat.position.lerpVectors(b.boat,b.destination,u*u*(3-2*u));player.position.copy(heroBoat.position);player.position.y+=.20;const delta=heroBoat.position.clone().sub(before);camera.position.add(delta);controls.target.add(delta);if(u===1){lastBoatPoint.copy(b.destination);boatGoal=.97;autoTravel=true;boarding=null;}return;}
 const before=player.position.clone(),u=Math.min(b.time/1.4,1);player.position.lerpVectors(b.from,b.boat.clone().add(new THREE.Vector3(0,.20,0)),u*u*(3-2*u));player.rotation.y=b.yaw;const delta=player.position.clone().sub(before);if(!aerial){camera.position.add(delta);controls.target.add(delta);}if(u===1){const eye=camera.position.clone(),look=controls.target.clone();parkedAtBank=false;enterScene('grove');sailingOut=true;returnedToCreek=false;const curve=worlds.grove.userData.curve;if(b.t!==null)boatT=b.t;else{let best=Infinity;for(let i=12;i<30;i++){const d=curve.getPoint(i/100).distanceToSquared(b.boat);if(d<best){best=d;boatT=i/100;}}}b.destination=curve.getPoint(boatT);b.destination.y=.15;b.undock=true;b.time=0;heroBoat.position.copy(b.boat);heroBoat.rotation.y=b.yaw;camera.position.copy(eye);controls.target.copy(look);tween=null;setLabels();}}

function walkBankToCave(){walkingToCave=true;autoTravel=requestWalk({x:7.5,z:-42});toast('沿桃树间的小路走到山口木板路。');}
function visitPeachBank(t=landingT){if(bankTransfer||sailingOut)return;if(groveWalking){autoTravel=requestWalk(landing);landingPending=true;return;}landingT=t;shorePoint=worlds.grove.userData.curve.getPoint(t);landing={x:shorePoint.x+8.8,z:shorePoint.z};landingY=bankFloor(landing.x,landing.z);groveShoreBoat.position.set(shorePoint.x+3.5,.15,landing.z);landingPending=true;boatGoal=landingT;autoTravel=true;toast('先在桃林溪岸停船，再上岸散步。');}
function updateBankTransfer(dt){const b=bankTransfer;b.time+=dt;const u=Math.min(b.time/1.3,1),ease=u*u*(3-2*u);const before=player.position.clone();if(b.back&&b.stage===2){heroBoat.position.lerpVectors(b.from,new THREE.Vector3(shorePoint.x,.15,shorePoint.z),ease);player.position.copy(heroBoat.position);player.position.y+=.2;}else if(!b.back&&b.stage===0){heroBoat.position.lerpVectors(b.from,new THREE.Vector3(shorePoint.x+3.5,.15,landing.z),ease);player.position.copy(heroBoat.position);player.position.y+=.2;}else player.position.lerpVectors(b.from,b.back?new THREE.Vector3(shorePoint.x+3.5,.35,landing.z):new THREE.Vector3(landing.x,landingY,landing.z),ease);const delta=player.position.clone().sub(before);camera.position.add(delta);controls.target.add(delta);if(u===1){if(b.back&&b.stage===1){b.stage=2;b.time=0;b.from=new THREE.Vector3(shorePoint.x+3.5,.15,landing.z);heroBoat.visible=true;heroBoat.position.copy(b.from);groveShoreBoat.visible=false;return;}if(!b.back&&b.stage===0){b.stage=1;b.time=0;b.from=player.position.clone();heroBoat.visible=false;groveShoreBoat.visible=true;}else{parkedAtBank=!b.back;groveWalking=!b.back;heroBoat.visible=b.back;groveShoreBoat.visible=!b.back;if(b.back){boatT=landingT;lastBoatPoint.copy(worlds.grove.userData.curve.getPoint(boatT));boatGoal=.12;autoTravel=true;}else{autoTravel=false;playerRing.visible=true;if(!aerial)tween={from:camera.position.clone(),to:player.position.clone().add(new THREE.Vector3(-8,7,8)),tf:controls.target.clone(),tt:player.position.clone().add(new THREE.Vector3(0,1,0)),start:performance.now(),duration:900};}bankTransfer=null;setLabels();}}}
function beginSeeking(){if($('#modal').open)$('#modal').close();if(seekingAgain){autoTravel=true;boatGoal=.12;return;}hasDeparted=true;seekingAgain=true;lostEnding=false;sailingOut=false;groveWalking=false;boarding=null;bankTransfer=null;landingPending=false;homeward=[];returnedToCreek=false;keys.clear();routeHistory.push({from:active,to:'return',reason:'离开桃源后，再寻旧路'});active='return';worlds.return.userData.curve=worlds.grove.userData.curve;for(const [key,w]of Object.entries(worlds))w.visible=key==='grove';lostPass.visible=true;mooredBoat.visible=false;groveShoreBoat.visible=false;heroBoat.visible=true;lastBoatPoint.copy(worlds.grove.userData.curve.getPoint(boatT));boatGoal=.12;autoTravel=true;endingShown=false;soundscape.setScene('return');scene.fog.near=15;scene.fog.far=90;scene.fog.color.set('#d4e0d8');scene.background.set('#d4e0d8');$('#title').textContent=data.return.name;$('#verse').textContent=data.return.verse;$('#scene-note').textContent='沿着旧日溪流回头寻找，山口却已无迹可寻。';$('#chapter').textContent='第 6 幕 / 六幕';$('#back').hidden=true;document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene==='return'));marker.visible=false;setLabels();toast('寻向所志，遂迷，不复得路。');}
function showLostEnding(){lostEnding=true;boatGoal=null;autoTravel=false;keys.clear();collect();modal('<div class="eyebrow">重寻不得</div><h2>山口已无迹可寻</h2><p>你沿溪辨认旧时的记号，走过的地方仿佛依旧，通往桃源的山口却再也找不到了。</p><p>寻向所志，遂迷，不复得路。</p><button class="primary" id="restart-journey">重新开始一段旅程</button>');$('#restart-journey').onclick=()=>location.href=location.pathname;}
function advance(){if(lostEnding){showLostEnding();return;}if(hasDeparted&&sailingOut&&!autoTravel){beginSeeking();return;}if(boarding)return;if(boardingApproach)return;if(returnedToCreek&&visitedVillage){boardForDeparture();return;}if(groveWalking){visitedVillage?boardForDeparture():visitPeachBank();return;}if(homeward.length){if(autoTravel){autoTravel=false;walkPath=[];}else autoTravel=requestWalk(homeward[0]);return;}if(active==='house'&&!farewellDone){beginFarewell();return;}if(seatState||seatApproach){if(seatState)toggleSeat();seatApproach=false;}if(transitioning||docking)return;if(autoTravel){autoTravel=false;boatGoal=null;walkPath=[];toast('已停下，可以自由观景。');return;}if(heroBoat.visible){boatGoal=sailingOut?.97:.12;autoTravel=true;toast(active==='grove'?'沿着溪水前行，到山脚系舟。':'沿旧路前行，寻找从前的记号。');return}if(active==='cave'){autoTravel=requestWalk({x:9,z:-70.2});toast('沿石隙向前走，出口就在光亮处。');return}const next=route[route.indexOf(active)+1];if(next)goToGateway(next)}
$('#advance').onclick=advance;
function updateDock(dt){if(!docking)return;docking.time+=dt;const u=Math.min(docking.time/1.15,1),ease=u*u*(3-2*u);const old=heroBoat.position.clone();heroBoat.position.lerpVectors(docking.start,new THREE.Vector3(3.5,.15,-42.8),ease);heroBoat.rotation.y=THREE.MathUtils.lerp(docking.yaw,Math.PI*.65,ease);const delta=heroBoat.position.clone().sub(old);camera.position.add(delta);controls.target.add(delta);if(docking.time<1.15){player.position.copy(heroBoat.position);player.position.y=.35}else{const v=Math.min((docking.time-1.15)/.8,1);player.position.lerpVectors(new THREE.Vector3(3.5,.35,-42.8),new THREE.Vector3(7.5,.65,-42),v);player.position.y=.35+.30*THREE.MathUtils.smoothstep(v,0,.3);player.rotation.y=Math.PI/2}if(docking.time>2){const eye=camera.position.clone(),look=controls.target.clone(),position=player.position.clone();collect();routeHistory.push({from:'grove',to:'cave',reason:'同一溪岸，系舟上岸'});docking=null;parkedAtBank=false;enterScene('cave');tween=null;player.position.copy(position);camera.position.copy(eye);controls.target.copy(look);controls.update();toast('小舟系在身后的溪边。沿岸边小道进入山口。')}}
function resetView(animate=true){const v=views[active],p=new THREE.Vector3(...v.pos),t=new THREE.Vector3(...v.target);if(innerWidth<600)p.sub(t).multiplyScalar(1.65).add(t);if(heroBoat.visible){const curve=worlds[active].userData.curve,offset=curve.getPoint(boatT).sub(curve.getPoint(.61));p.add(offset);t.add(offset)}controls.minDistance=v.min;controls.maxDistance=aerial?450:innerWidth<600?v.max*1.7:v.max;if(animate&&!reduced)tween={from:camera.position.clone(),to:p,tf:controls.target.clone(),tt:t,start:performance.now(),duration:900};else{camera.position.copy(p);controls.target.copy(t);controls.update()}}
function enterScene(id,options={}){if(!worlds[id])return;if(hasDeparted){beginSeeking();return;}groveWalking=false;bankTransfer=null;landingPending=false;groveShoreBoat.visible=false;gathering=false;farewellPending=false;farewellDone=false;seatState=null;seatApproach=false;boatStrokeActive=false;rowingStrength=0;soundscape.setScene(id);if(!options.preserveTransition){sceneTransition=null;transitioning=false;$('#transition').classList.remove('show');$('#transition').style.opacity='';}docking=null;autoTravel=false;walkPath=[];entryAge=0;caveWideView=false;controls.enabled=true;
 active=id;if(['overview','pond','house'].includes(id))visitedVillage=true;const villageLighting=['overview','pond','house'].includes(id);sun.target.position.set(villageLighting?9:0,0,villageLighting?-104:0);sun.position.set(sun.target.position.x-35,65,sun.target.position.z+25);Object.entries(worlds).forEach(([k,g])=>g.visible=id==='return'?k==='return':['grove','cave','pond','house'].includes(k));mooredBoat.visible=['cave','overview','pond','house'].includes(id);player.position.set(0,.2,id==='house'?13.5:8);if(id==='house')player.position.set(HX,.25,HZ+13.5);if(id==='pond')player.position.set(1,.25,-96);if(id==='overview')player.position.set(9,.25,-70);if(id==='cave')player.position.set(7.5,.65,-42);player.userData.rig.phase=0;posePerson(player,0,1);player.position.y=nav[id]?.floor(player.position.x,player.position.z)??.25;walkTarget=null;keys.clear();boatT=.61;boatGoal=null;heroBoat.visible=id==='grove'||id==='return';if(heroBoat.visible)lastBoatPoint.copy(worlds[id].userData.curve.getPoint(boatT));playerRing.visible=!heroBoat.visible;syncParkedBoat();scene.fog.near=id==='return'?12:95;scene.fog.far=id==='return'?65:220;scene.background.set(id==='return'?'#d4e0d8':'#c7e0e5');scene.fog.color.copy(scene.background);
 marker.visible=!collected.has(id);controls.maxPolarAngle=id==='house'?Math.PI*.40:Math.PI*.47;marker.position.fromArray(data[id].item);$('#title').textContent=data[id].name;$('#verse').textContent=data[id].verse;$('#scene-note').textContent=data[id].note;$('#back').hidden=id==='grove';$('#back').textContent=id==='overview'?'← 回到桃林':id==='cave'?'← 看溪边小舟':'← 村落全景';$('#advance').textContent=routeText[id];$('#chapter').textContent='第 '+(route.indexOf(id)+1)+' 幕 / 六幕';document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===id));setLabels();if(!aerial)resetView();else{controls.maxDistance=450;scene.fog.near=250;scene.fog.far=700;}renderer.shadowMap.needsUpdate=true;
 if(id!=='grove')toast(data[id].verse);
}

function updateProgress(){ $('#count').textContent=collected.size+' / 6';document.querySelectorAll('[data-scene]').forEach(b=>{b.classList.toggle('collected',collected.has(b.dataset.scene));b.querySelector('em').textContent=collected.has(b.dataset.scene)?'✓':'↗'});$('#progress-hint').textContent=collected.size===6?'六景已拾齐，桃源已在心中':`六幕旅程，${collected.size?`已记下 ${collected.size} 页`:'六页山中记忆'}`}
function collect(){if(collected.has(active))return;const id=active;collected.add(id);try{localStorage.setItem('taoyuan-memories',JSON.stringify([...collected]))}catch{}marker.visible=false;setLabels();updateProgress();chime();toast('已拾得「'+data[id].memory+'」 · '+collected.size+' / 6');}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function journal(){modal('<div class="eyebrow">COLLECTED MOMENTS</div><h2>一册山中手记</h2><p>不必带走什么，记得此刻就好。已拾景 '+collected.size+' / 6</p>'+Object.entries(data).map(([id,d])=>`<div class="entry ${collected.has(id)?'':'locked'}"><h3>${collected.has(id)?'✿':'○'} ${d.memory} · ${d.name}</h3><p>${collected.has(id)?d.text:'走进这一处风景，寻找金色的记忆。'}</p></div>`).join('')+'<p>场景与引文取意自陶渊明《桃花源记》；拾景、酒饭互动和荷花为游戏化演绎。</p><a class="source" href="https://www.gushiwen.cn/shiwenv_73add8822103.aspx" target="_blank" rel="noopener">阅读《桃花源记》原文 ↗</a><br><button class="secondary" id="clear-progress">重新拾景</button>');$('#clear-progress').onclick=()=>{collected.clear();endingShown=false;try{localStorage.removeItem('taoyuan-memories')}catch{}updateProgress();setLabels();marker.visible=true;if(marker.visible)marker.position.fromArray(data[active].item);$('#modal').close();toast('手记已翻到新的一页。')}}
function showEnding(){modal('<div class="eyebrow">THE VALLEY IS WITHIN YOU</div><h2>心中自有桃花源</h2><p>桃花、天光、田园、酒饭，还有一段归途。<br>六页记忆，装下了山中的一天。</p><div class="entry"><p>后来，渔人再寻桃源，遂迷，不复得路。<br>而你可以选择，把这份安宁留在心里。</p></div><button class="primary" id="stay">留在桃源，再走一走</button><button class="secondary" id="leave">携记忆归去 →</button>');$('#stay').onclick=()=>$('#modal').close();$('#leave').onclick=()=>{$('#modal').close();enterScene('grove');toast('溪水依旧，桃花如初。愿你在人间，也有自己的桃花源。')}}
$('#journal').onclick=journal;$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});$('#help').onclick=()=>modal('<div class="eyebrow">A LITTLE GUIDE</div><h2>慢慢走，不必赶路</h2><div class="entry"><h3>观山水</h3><p>拖拽画面旋转视角；滚轮或右侧 ＋ / − 缩放。双指捏合可缩放，双指拖动可平移。</p></div><div class="entry"><h3>入画中</h3><p>点击底部六张场景卡自由探索，或点击右下角按钮依次游历六幕。桃林中按 W / S 划船，或点击水面；相机会跟随小舟，到溪流尽头自动系舟上岸。按 E 或右下角按钮可自动沿路前行。村中点击地面会自动绕开桌床、池塘和房屋，也可用 WASD 或方向键移动；走近场景入口会自动进入。Esc 返回全景。</p></div><div class="entry"><h3>拾一景</h3><p>每处场景有一枚金色记忆，点击标记即可收集。走近后按空格也可拾取。集齐六景，完成你的山中手记。进度会保存在此浏览器。</p></div><p>点击桌边“坐下”可休息，再点“起身”或方向键继续行走。点击“听音乐”开启全程背景音乐；“听环境”单独控制溪流、虫鸟和轻声脚步。右侧“截图”可保存无界面的风景照片。</p>');
$('#back').onclick=()=>{if(transitioning)return;if(active==='cave'){walkPath=[];autoTravel=false;keys.clear();caveWideView=true;resetView();return}if(active==='house'){changeConnectedScene('pond','走回田间');return}if(active==='pond'){changeConnectedScene('overview','退远看整座村落');return}enterScene(active==='overview'?'grove':'overview')};document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{homeward=[];boardingApproach=false;returnedToCreek=false;boarding=null;sailingOut=false;const to=b.dataset.scene;if(to==='house'&&['overview','pond'].includes(active)){goToGateway('house');return}if(['overview','pond','house'].includes(active)&&['overview','pond','house'].includes(to)&&to!==active){changeConnectedScene(to,'同一村落，切换观察距离');return}enterScene(to)});function toggleAerial(){aerial=!aerial;tween=null;controls.enabled=true;if(aerial){aerialSaved={eye:camera.position.clone(),look:controls.target.clone()};controls.target.set(15,0,-50);camera.position.set(15,180,30);controls.maxDistance=450;controls.panSpeed=1.1;controls.mouseButtons.LEFT=THREE.MOUSE.PAN;controls.mouseButtons.RIGHT=THREE.MOUSE.ROTATE;controls.touches.ONE=THREE.TOUCH.PAN;controls.touches.TWO=THREE.TOUCH.DOLLY_ROTATE;scene.fog.near=250;scene.fog.far=700;}else{controls.panSpeed=.55;camera.position.copy(aerialSaved.eye);controls.target.copy(aerialSaved.look);controls.mouseButtons.LEFT=THREE.MOUSE.ROTATE;controls.mouseButtons.RIGHT=THREE.MOUSE.PAN;controls.touches.ONE=THREE.TOUCH.ROTATE;controls.touches.TWO=THREE.TOUCH.DOLLY_PAN;controls.maxDistance=views[active].max;scene.fog.near=95;scene.fog.far=220;}$('#aerial span').textContent=aerial?'回到身边':'高空俯瞰';controls.update();}$('#aerial').onclick=toggleAerial;
